/**
 * Public-build stub for the ASCII field document seam.
 *
 * The registered CompleteShelf source bundle ships only its four registered
 * files; LandingPages.tsx marks this import with "Same seam for the ASCII
 * field's three generated sibling scenes" — generated by
 * `scripts/build-ascii-scenes.mjs` in the full build and guarded out of the
 * public one. The module is absent from the published `@designcodeio/threeui`
 * package and from the public MengTo/threeui repository, so no authored scene
 * documents are invented here.
 *
 * The registered call site is direct (`buildAsciiFieldDocument(safeVariant)`),
 * so the stub is a function that returns `undefined`: `srcDoc` stays empty and
 * the frame falls back to the page's own sourceUrl. Only AsciiPageTransition
 * entries reach this seam — CompleteShelfLandingPage never does.
 */
export function buildAsciiFieldDocument(_variant: string): string | undefined {
  return undefined;
}
